import React from 'react';

function lessonPage(title, lead, concept, code, example, takeaway) {
  return {
    title,
    content: (
      <>
        <p className="lesson-lead">{lead}</p>
        <section className="lesson-topic">
          <h3>Core idea</h3>
          <p>{concept}</p>
          <pre><code>{code}</code></pre>
        </section>
        <section className="lesson-topic">
          <h3>Apply the idea</h3>
          <p>{example}</p>
        </section>
        <p className="lesson-takeaway">{takeaway}</p>
      </>
    ),
  };
}

function javaLecture(title, pages) {
  return {
    title,
    pages: pages.map((page) => lessonPage(...page)),
  };
}

